import { Dimensions } from 'react-native';

const { width } = Dimensions.get('window');

import { StyleSheet } from 'react-native';

export const styles = StyleSheet.create({
  // 原有样式保留，新增以下样式
  calendarHeaderWrapper: {
    paddingVertical: 8,
  },
  calendarMonthTitle: {
    textAlign: 'center',
    fontSize: 16,
    fontWeight: '500',
    marginBottom: 6,
  },
  weekDaysContainer: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
  },
  weekDayText: {
    flex: 1,
    textAlign: 'center',
    fontSize: 14,
    color: '#666',
  },
  calendarDayText: {
    textAlign: 'center',
    fontSize: 16,
    color: '#333',
  },
  disabledDayText: {
    color: '#ccc',
  },
  selectedDayText: {
    color: 'white',
    fontWeight: 'bold',
  },
  todayDayText: {
    fontWeight: 'bold',
  },

  // 原有基础样式
  modalContainer: {
    flex: 1,
    backgroundColor: '#fff',
  },
  modalHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
  },
  cancelText: {
    fontSize: 16,
    color: '#007AFF',
  },
  modalTitle: {
    fontSize: 18,
    fontWeight: '500',
  },
  footerInfo: {
    padding: 16,
    alignItems: 'center',
  },
  footerText: {
    fontSize: 14,
    color: '#666',
  },
});
